=====test11.rs=====
     1	//! Rust port of `tests/test11.cpp` from the immer test-suite.
     2	//!
     3	//! The original builds an `immer::vector<int>` one `push_back` at a time, sums
     4	//! it, builds a second vector holding every element doubled, and prints both
     5	//! sums. This file is a line-for-line translation; everything it leans on lives
     6	//! in the modules under `src/`:
     7	//!
     8	//! * `immer::Vector` — the persistent vector re-implemented from scratch
     9	//!   (bit-partitioned trie, branching factor 32, structural sharing).
    10	//! * `cpp::stoi` — `std::stoi`, including its two exception cases.
    11	//! * `cpp::cint` — `int` arithmetic with two's-complement wrap-around.
    12	//!
    13	//! The `#[path]` attributes let this one file be built either way:
    14	//!
    15	//! ```text
    16	//! rustc -O test11.rs        # standalone
    17	//! cargo build --release     # as the `test11` binary target
    18	//! ```
    19	
    20	#[path = "src/cpp/mod.rs"]
    21	mod cpp;
    22	#[path = "src/immer/mod.rs"]
    23	mod immer;
    24	
    25	use crate::cpp::cint::{self, CInt};
    26	use crate::cpp::stoi::{stoi, terminate_with_uncaught_exception};
    27	use crate::immer::Vector;
    28	
    29	fn main() {
    30	    // int n = (argc > 1) ? std::stoi(argv[1]) : 11;
    31	    // `argv[1]` exists exactly when `argc > 1`.
    32	    let n: CInt = match cpp::cli::arg(1) {
    33	        Some(argument) => match stoi(&argument) {
    34	            Ok(value) => value,
    35	            // Uncaught in the original, so the process aborts with the C++
    36	            // runtime's banner on stderr.
    37	            Err(error) => terminate_with_uncaught_exception(error),
    38	        },
    39	        None => 11,
    40	    };
    41	
    42	    // auto v = immer::vector<int>{};
    43	    // for (int i = 0; i < n; ++i) v = v.push_back(i + 1);
    44	    let mut v: Vector<CInt> = Vector::new();
    45	    let mut i: CInt = 0;
    46	    while i < n {
    47	        v = v.push_back(cint::add(i, 1));
    48	        i = cint::add(i, 1);
    49	    }
    50	
    51	    // auto sum = 0; for (auto x : v) sum += x;
    52	    let mut sum: CInt = 0;
    53	    for x in &v {
    54	        sum = cint::add(sum, *x);
    55	    }
    56	
    57	    // std::cout << sum << std::endl;
    58	    println!("{}", sum);
    59	
    60	    // auto v2 = immer::vector<int>{};
    61	    // for (int i = 0; i < v.size(); ++i) v2 = v2.push_back(v[i] * 2);
    62	    let mut v2: Vector<CInt> = Vector::new();
    63	    for i in 0..v.size() {
    64	        v2 = v2.push_back(cint::mul(v[i], 2));
    65	    }
    66	
    67	    // sum = 0; for (auto x : v2) sum += x;
    68	    sum = 0;
    69	    for x in &v2 {
    70	        sum = cint::add(sum, *x);
    71	    }
    72	
    73	    // std::cout << sum << std::endl;
    74	    println!("{}", sum);
    75	}
